// Fixed history纯数学/冷结构回归，不伪装真实Growth接受或Condition来源验收。
#include "resident/kernel/fixed_service_history.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
// 每个失败终止本目标，保首错信息。
void check(bool ok,const char* s){if(!ok)throw std::runtime_error(s);}
template<class T>T take(Outcome<T> r){if(!r.ok)throw std::runtime_error(r.error.original.code);return std::move(r.value);}
CanonicalFraction f(const char* n,const char* d){return take(normalize_fraction(n,d));}
SourceRef source(const char* id){return {"growth","growth_fixed_service_boundary",id};}
// 此处只构造数学测试值；真实来源存在性不在本测试宣称范围内。
FixedServiceTransition initial(){FixedServiceTransition t;t.transition_id="t0";t.action_ref="a";t.occurred_at={10,f("1","3")};t.execution_source_ref={"growth","life_activity","a"};t.execution_source_schema=1;t.cause=FixedOwnerAdopted{source("start"),1};t.input_basis_refs={FixedAppliedInput{source("start"),1}};return t;}
ActionElapsedStore started(){ActionElapsedStore s;s.entries.push_back(take(begin_fixed_elapsed("a","a","rest-rule","a",{10,f("1","3")},1,{"N",1,12})));s.fixed_service_transitions.push_back(initial());return s;}
// 真实技术片不增transition，尾信用由唯一entry精确反验。
void running_tail(){auto s=started();auto piece=take(prepare_fixed_elapsed_slice(s.entries[0],{{10,f("1","3")},{10,f("7","12")}}, {"N",1,12}));s.entries[0].credited_units=piece.credited_units;s.entries[0].last_settled_at=piece.last_settled_at;check(validate_fixed_history_values(s,piece.last_settled_at,{"N",1,12}).ok,"tail valid");auto view=take(read_fixed_service_intervals(s,"a",s.entries[0].started_at,piece.last_settled_at,piece.last_settled_at,{"N",1,12}));check(view.complete&&view.intervals.size()==1&&!view.intervals[0].closing_transition_ref,"tail interval");s.entries[0].credited_units={f("4","1")};check(!validate_fixed_history_values(s,piece.last_settled_at,{"N",1,12}).ok,"forged credit denied");}
// 暂停空档不供服务，同M恢复可行但仅数学链不授业务暂停权限。
void suspension_and_terminal(){auto s=started();auto& e=s.entries[0];auto piece=take(prepare_fixed_elapsed_slice(e,{e.started_at,{10,f("7","12")}}, {"N",1,12}));e.credited_units=piece.credited_units;e.last_settled_at=piece.last_settled_at;e.timing=ElapsedSuspended{"stop"};auto stop=initial();stop.transition_id="t1";stop.transition_ordinal=1;stop.previous_transition_ref="t0";stop.kind=FixedTransitionKind::suspended;stop.occurred_at=e.last_settled_at;stop.credited_at=e.credited_units;stop.cause=FixedOwnerStateChanged{source("stop"),1,"original-stop-rule"};stop.previous_input_basis_refs=s.fixed_service_transitions.back().input_basis_refs;s.fixed_service_transitions.push_back(stop);check(validate_fixed_history_values(s,{100,{}},{"N",1,12}).ok,"suspended no service");
    auto resume=stop;resume.transition_id="t2";resume.transition_ordinal=2;resume.previous_transition_ref="t1";resume.kind=FixedTransitionKind::resumed;resume.occurred_at={100,{}};resume.cause=FixedOwnerStateChanged{source("resume"),1,"original-resume-rule"};s.fixed_service_transitions.push_back(resume);e.last_settled_at=resume.occurred_at;e.timing=ElapsedRunning{{100,f("3","4")}};check(validate_fixed_history_values(s,e.last_settled_at,{"N",1,12}).ok,"resumed remaining only");
    auto done=take(prepare_fixed_elapsed_slice(e,{e.last_settled_at,{100,f("3","4")}}, {"N",1,12}));e.credited_units=done.credited_units;e.last_settled_at=done.last_settled_at;e.timing=ElapsedTerminal{"a"};auto terminal=resume;terminal.transition_id="t3";terminal.transition_ordinal=3;terminal.previous_transition_ref="t2";terminal.kind=FixedTransitionKind::terminal;terminal.occurred_at=e.last_settled_at;terminal.credited_at=e.credited_units;terminal.cause=FixedOwnerTerminated{source("finish"),1};terminal.previous_input_basis_refs=resume.input_basis_refs;terminal.input_basis_refs.clear();terminal.terminal_disposition=FixedTerminalDisposition::completed;s.fixed_service_transitions.push_back(terminal);ActionElapsedTerminalBinding binding;binding.action_ref="a";binding.action_kind="service";binding.actor_id="actor";binding.participant_actor_ids={"actor","provider"};binding.original_execution_source_ref={"growth","life_activity","a"};binding.started_source_ref=MomentOwnerSource{source("start"),1};binding.ended_source_ref=MomentOwnerSource{source("finish"),1};binding.terminal_result_ref="a";s.terminal_bindings.push_back(binding);check(validate_fixed_history_values(s,e.last_settled_at,{"N",1,12}).ok,"terminal exact chain");auto view=take(read_fixed_service_intervals(s,"a",e.started_at,e.last_settled_at,e.last_settled_at,{"N",1,12}));check(view.complete&&view.intervals.size()==2,"pause not service interval");check(take(compare_fractions(view.credited_after.value,e.required_units.value))==0,"exact one service");s.fixed_service_transitions[2].credited_at={f("4","1")};check(!validate_fixed_history_values(s,e.last_settled_at,{"N",1,12}).ok,"suspended credit mutation denied");}
// 孤源、重复ID、自指与伪开始都是结构失败，不能在restore中补做执行。
void malformed(){auto s=started();s.fixed_service_transitions.clear();check(!validate_fixed_history_values(s,{10,f("1","3")},{"N",1,12}).ok,"missing history");s=started();s.fixed_service_transitions[0].execution_source_ref={"action_elapsed","fixed_service_transition","t0"};check(!validate_fixed_history_values(s,{10,f("1","3")},{"N",1,12}).ok,"self source");s=started();s.fixed_service_transitions.push_back(s.fixed_service_transitions[0]);check(!validate_fixed_history_values(s,{10,f("1","3")},{"N",1,12}).ok,"duplicate source");s=started();s.fixed_service_transitions[0].input_basis_refs.push_back(s.fixed_service_transitions[0].input_basis_refs[0]);check(!validate_fixed_history_values(s,{10,f("1","3")},{"N",1,12}).ok,"duplicate input");}
}
int main(){try{running_tail();suspension_and_terminal();malformed();std::cout<<"fixed_service_history value tests passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
